import{_ as e,o,c as n,a as r}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const d=JSON.parse('{"title":"Стоимость не-внедрения ИИ","description":"","frontmatter":{"site":"pro","title":"Стоимость не-внедрения ИИ","date":"2026-09-22T00:00:00.000Z","source":"https://t.me/jfyi_ps/86","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-09-22-stoimost-ne-vnedreniya-ii"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Стоимость не-внедрения ИИ"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-09-22-stoimost-ne-vnedreniya-ii"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Стоимость не-внедрения ИИ"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Стоимость не-внедрения ИИ\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-09-22-stoimost-ne-vnedreniya-ii\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-09-22\\"}"]]},"headers":[],"relativePath":"posts/2026-09-22-stoimost-ne-vnedreniya-ii.md","filePath":"posts/2026-09-22-stoimost-ne-vnedreniya-ii.md"}'),i={name:"posts/2026-09-22-stoimost-ne-vnedreniya-ii.md"};function s(a,t,p,m,g,c){return o(),n("div",null,[...t[0]||(t[0]=[r("<p><strong>Ситуация</strong> Проект переезжал в другое облако. Часть людей, которые держали знание в голове, не переехала, и когда основная точка входа в мобильном приложении отвалилась, поддержка села втрое плотнее и выдала девять критичных дефектов. Я был новым человеком на проекте, но за час собрал загрузчики, которые складывали код, задачи и чаты текстовыми файлами рядом, и написал разбор, где чинить и сколько займёт.</p><p><strong>Проблема</strong> Знание размазано по чатам, документам, задачам и головам, и вместе с человеком оно уходит. Дорогие эксперты отвечают на один и тот же вопрос по пять раз, ответ ищется часами, новичок выходит на продуктивность месяцами. Обычный чат с моделью это не лечит, потому что ответ должен быть актуальным, со ссылкой на источник и не уходить в чужое облако.</p><p><strong>Решение</strong> База знаний по всем вашим источникам, которая отвечает строго по найденным документам и всегда актуально. У российского провайдера один сложный вопрос выходит от тридцати копеек до нескольких рублей, индексирование 5-20 тысяч документов до трёх тысяч рублей разово, а год пилота на четыре тысячи вопросов укладывается в 5-20 тысяч рублей. На своём сервере с видеокартой на 24 ГБ, это 450-700 тысяч рублей разово и 2-5 тысяч в месяц на электричество.</p><p><strong>Результат</strong> Команда из 19 человек теряла 108 часов в неделю на поиск и повторные объяснения, это около 600 тысяч рублей в месяц и порядка 7 миллионов в год. Против этого инфраструктура стоит 450-700 тысяч разово или 5-20 тысяч в год на API. За неделю меня тегнули 115 раз, потому что я всегда находил актуальный ответ. На бенчмарке DRAGON система ответила верно на 80,3% вопросов при нуле выдуманных цитат (первое место).</p><p><strong>Методология</strong> Прототип проверяется за 8 недель. Нужен один инженер и эксперт от бизнеса на пару часов в неделю. Подключаем два-три источника и собираем 50-100 реальных вопросов, считаем базовый поиск, потом включаем улучшения по одному, сперва граф знаний, затем переранжирование, следом рассуждения, и каждый раз меряем вклад отдельно. Успех это 70% ответов с корректным фактом и ссылкой, ноль выдуманных цитат и хотя бы десять активных пользователей к концу пилота.</p><p><strong>Как применить в вашей компании</strong> Если у вас более 20 человек на созвонах где никто не &quot;шарит&quot; экран, информация размазана по чатам и документам, а люди тратят больше часа в день на поиск, вам подойдёт тот же подход. Подключите к базе два-три главных источника, соберите список реальных вопросов, дайте базе неделю на них ответить и сравните с тем, как вы ищете сейчас. Если разница есть, включайте улучшения по одному и расширяйте на остальные команды.</p>",6)])])}const u=e(i,[["render",s]]);export{d as __pageData,u as default};
